contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, address beneficiary) public payable {
        require(amount > 0);

        // Freshly deployed c: the caller (this test contract) must hold zero credits.
        uint256 creditsBefore = c.imBalances(address(this));
        require(creditsBefore == 0);

        // Sanity setup: a successful supply to `beneficiary` must not grant
        // credits to the caller (msg.sender == this contract).
        bool supplyReverted;
        try c.supplyTokenTo(0, beneficiary) {
            supplyReverted = false;
        } catch {
            supplyReverted = true;
        }

        // Deciding call: redeeming a positive amount with zero credits must revert.
        bool reverted;
        try c.redeemToken(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            reverted
            && c.imBalances(address(this)) == creditsBefore
            && (supplyReverted || c.imBalances(beneficiary) == 0)
        );
    }

    receive() external payable {}
}

