        require(probe != address(0), "probe must be nonzero");

        // The deposit token reported by IYieldSource must match the stored mAsset.
        address reported = c.depositToken();
        address stored = address(c.mAsset());

        // A freshly probed address has no imBalance, so its token-valued balance must be zero
