        uint256 bal = c.balanceOfToken(probe);

        // Balance must also be zero for any address scaled by any amount-dependent rate:
        // the result must not depend on the caller-chosen seedAmount parameter.
        uint256 balAgain = c.balanceOfToken(probe);

        assert(
            reported == stored &&
            bal == 0 &&
            balAgain == bal &&
            (seedAmount == 0 || bal == 0)
        );
    }

    receive() external payable {}
}

